import unittest
import re
from main import run

class TestFindTODOandFIXME(unittest.TestCase):
    def test_no_comments(self):
        input_data = [{"files": {"a.tsx": "const x = 10;"}}]
        expected_output = {"findings": []}
        self.assertEqual(run(input_data), expected_output)

    def test_single_todo_comment(self):
        input_data = [{"files": {"b.tsx": "const x = 10; // TODO: Fix this"}}]
        expected_output = {
            "findings": [
                {"file": "b.tsx", "line": 1, "comment": "TODO: Fix this"}
            ]
        }
        self.assertEqual(run(input_data), expected_output)

    def test_multiple_comments(self):
        input_data = [
            {"files": {"c.tsx": "const x = 10; // TODO: Fix this\nconst y = 20; // FIXME: Remove this"}}
        ]
        expected_output = {
            "findings": [
                {"file": "c.tsx", "line": 1, "comment": "TODO: Fix this"},
                {"file": "c.tsx", "line": 2, "comment": "FIXME: Remove this"}
            ]
        }
        self.assertEqual(run(input_data), expected_output)

if __name__ == '__main__':
    unittest.main()
